let method = $json.method;
if (!method) { method = $json.headers?.[':method'] || 'POST'; }
return [{ json: { ...$json, method: method } }];

const body = $json.body;
if (!body || typeof body !== 'object') throw new Error('400: Missing body');

const safeArray = v => Array.isArray(v) ? v : (v ? [v] : []);
const normaliseAge = arr => arr.map(v => {
  if (v === 'Kids')      return 'Kids_0_12';
  if (v === 'Teens')     return 'Teens_13_19';
  if (v === 'Adults')    return 'Adults_20_39';
  if (v === 'MiddleAge') return 'Adults_40_59';
  if (v === 'Seniors')   return 'Seniors_60plus';
  return v;
});

const flexDates = body.flexDates === 'yes' || body.flexDates === true || body.flexDates === 'true';
const tripMode  = body.tripMode || 'single';

// Parse multi-destination legs if present
let destinationLegs = null;
if (tripMode === 'multi' && body.destinationLegs) {
  try {
    const parsed = typeof body.destinationLegs === 'string'
      ? JSON.parse(body.destinationLegs)
      : body.destinationLegs;
    if (Array.isArray(parsed) && parsed.length >= 2) {
      destinationLegs = parsed.map(l => ({
        city:    (l.city    || '').trim(),
        checkIn: l.checkIn  || '',
        checkOut:l.checkOut || ''
      })).filter(l => l.city);
    }
  } catch(e) { /* fall back to single */ }
}

// Validate single-mode dates
if (!destinationLegs && !flexDates && body.startDate && body.endDate) {
  const s = new Date(body.startDate), e = new Date(body.endDate);
  if (isNaN(s) || isNaN(e)) throw new Error('400: Invalid dates');
  if (e < s) throw new Error('400: endDate before startDate');
}

// Derive summary fields from legs for display/email
const derivedCity  = destinationLegs ? destinationLegs.map(l => l.city).join(' → ') : (body.destinationCity || body.destination || '').trim();
const derivedStart = destinationLegs ? destinationLegs[0].checkIn : (body.startDate || '');
const derivedEnd   = destinationLegs ? destinationLegs[destinationLegs.length - 1].checkOut : (body.endDate || '');

return [{ json: {
  departureLocation:  (body.departureLocation || body.departure || '').trim(),
  destinationCity:    derivedCity,
  startDate:          derivedStart,
  endDate:            derivedEnd,
  flexDates,
  tripMode,
  destinationLegs,
  tripType:           body.tripType   || body.groupSize || 'Not specified',
  travelPace:         body.travelPace || 'Balanced',
  budgetTier:         body.budgetTier || 'Standard',
  groupSize:          body.groupSize  || '1',
  ageRange:           normaliseAge(safeArray(body.ageRange)),
  accommodationType:  body.accommodationType || body.propertyType || 'No preference',
  amenities:          safeArray(body.amenities),
  bedrooms:           body.bedrooms   || '1',
  bathrooms:          body.bathrooms  || '1',
  travelMode:         body.travelMode || 'flight',
  budget:             body.budget     || '0',
  email:              (body.email     || '').trim()
}}];

const {
  departureLocation, destinationCity, startDate, endDate, flexDates,
  tripMode, destinationLegs, travelMode,
  tripType, travelPace, budgetTier, groupSize, ageRange,
  accommodationType, amenities, bedrooms, bathrooms, budget, email
} = $json;

const fmt = v => Array.isArray(v) && v.length ? v.join(', ') : 'No preference';

const paceLabel = {
  Relaxed:  'Relaxed & slow (max 2 activities/day, linger at the property)',
  Balanced: 'Balanced (3–4 activities/day — explore the city, return to your stay each evening)',
  Active:   'Packed & active (full days, early starts, come home to rest)',
}[travelPace] || travelPace;

const tierLabel = {
  Economy:  'Economy — budget hotels, hostels, or budget Airbnb rooms; local transport, street food',
  Standard: 'Standard — 3-4 star hotels, quality Airbnb apartments or entire homes; good local restaurants',
  Elite:    'Elite — 5-star hotels, luxury villas, private pools, concierge service, fine dining',
}[budgetTier] || budgetTier;


const modeLabel = {
  flight: 'Flying — include flight recommendations with airline, route, price and Skyscanner/Google Flights booking link',
  drive:  'Driving — replace the Flights section with a Road Trip Route section: estimated drive time, scenic stops, fuel cost, parking. Do NOT recommend flights.',
  train:  'Train — replace the Flights section with a Rail Journey section: operators, journey time, key stations, booking links (Rome2rio/Trainline). Do NOT recommend flights.',
  bus:    'Bus — replace the Flights section with a Bus Route section: operators, journey time, terminal info, booking links (Rome2rio/FlixBus). Do NOT recommend flights.',
  ferry:  'Ferry — replace the Flights section with a Ferry Crossing section: operator names, crossing time, port logistics. Do NOT recommend flights.',
}[travelMode] || 'Flying';

let prompt;

if (tripMode === 'multi' && destinationLegs && destinationLegs.length >= 2) {
  // ── MULTI-DESTINATION PROMPT ──────────────────────────────────
  const totalNights = destinationLegs.reduce((sum, l) => {
    if (!l.checkIn || !l.checkOut) return sum;
    const n = Math.round((new Date(l.checkOut) - new Date(l.checkIn)) / 86400000);
    return sum + (n > 0 ? n : 0);
  }, 0);

  const legsText = destinationLegs.map((l, i) =>
    `  Stop ${i + 1}: ${l.city}\n    Check-in: ${l.checkIn}  →  Check-out: ${l.checkOut}\n    Nights: ${Math.round((new Date(l.checkOut) - new Date(l.checkIn)) / 86400000)}`
  ).join('\n\n');

  const routeSummary = destinationLegs.map(l => l.city).join(' → ');

  prompt = `Please create a complete multi-destination city & stays itinerary. CRITICAL: The Accommodation Type field tells you exactly what the user wants — match ALL accommodation recommendations to that type (hotel → Booking.com/Hotels.com links; Airbnb → airbnb.com; hostel → Hostelworld; etc.).

- Departure: ${departureLocation}
- Travel Mode: ${modeLabel}
- Trip Route: ${routeSummary}
- Total Duration: ${totalNights} nights
- Trip Type: ${tripType}
- Travel Pace: ${paceLabel}
- Plan Tier: ${tierLabel}
- Total Budget: $${budget} USD
- Group Size: ${groupSize}
- Age Ranges: ${fmt(ageRange)}
- Accommodation Type: ${accommodationType}
- Key Amenities: ${fmt(amenities)}
- Bedrooms: ${bedrooms}, Bathrooms: ${bathrooms}

Destination Legs:
${legsText}

For EACH stop, provide:
1. Flights / Transport: How to get there from the previous stop (or from departure airport for Stop 1). Include transport type, duration, estimated cost, and booking link.
2. Accommodation Options: 2–3 options matching the accommodation type and tier. Include name, price/night, total for the stay, and booking link.
3. Best Neighbourhoods: 1–2 areas to stay with pros/cons and a search link.
4. Daily Schedule: Morning/Afternoon/Evening for each day at that stop. Density based on travel pace.
5. Must-Visit Spots: 3–5 top attractions with booking/info links.
6. Dining Guide: 3–5 restaurant recommendations matching tier, with cuisine, price range, link.

After all stops:
- Multi-Destination Travel Tips: Packing tips, transport between cities, luggage storage, SIM cards, currency.
- Estimated Cost Summary (tab-separated): Flights, Accommodation per stop, Activities total, Food total, Transport between stops, Total, Remaining Budget.

Formatting rules:
- No Markdown (no ###, **, | tables)
- Section headings: plain text ending with colon
- Stop headings: <strong>Stop [N]: [City] ([dates])</strong>
- Day labels: <strong>Day [N]: [description]</strong>
- Bullets: leading hyphen (- item)
- Cost Summary: tab-separated (Category\tAmount)
- <strong> on Total and Remaining Budget rows
- Blank line between sections
- Emojis welcome but purposeful
- Every accommodation, transport, restaurant, and activity must have a real clickable booking link using <a href="URL">text →</a> format`;

} else {
  // ── SINGLE DESTINATION PROMPT (original) ─────────────────────
  const dateLine = flexDates
    ? 'Flexible — suggest the optimal time to visit this destination'
    : (startDate && endDate ? `${startDate} to ${endDate}` : 'Not specified');

  prompt = `Please create a complete city & stays itinerary. CRITICAL: The Accommodation Type field tells you exactly what the user wants — match ALL accommodation recommendations to that type (hotel → recommend hotels with Booking.com/Hotels.com links; Airbnb → recommend Airbnb homes; hostel → recommend hostels; etc.). Do not recommend Airbnb if they want a hotel and vice versa.

- Departure: ${departureLocation}
- Travel Mode: ${modeLabel}
- Destination: ${destinationCity}
- Dates: ${dateLine}
- Trip Type: ${tripType}
- Travel Pace: ${paceLabel}
- Plan Tier: ${tierLabel}
- Total Budget: $${budget} USD
- Group Size: ${groupSize}
- Age Ranges: ${fmt(ageRange)}
- Accommodation Type: ${accommodationType}
- Key Amenities: ${fmt(amenities)}
- Bedrooms: ${bedrooms}, Bathrooms: ${bathrooms}

Please follow all formatting and content rules from the system prompt exactly.`;
}

return [{ json: {
  departureLocation, destinationCity, startDate, endDate, flexDates,
  tripMode, destinationLegs, travelMode,
  tripType, travelPace, budgetTier, groupSize, ageRange,
  accommodationType, amenities, bedrooms, bathrooms, budget, email, prompt
}}];

// ── Validate OpenAI response & format ─────────────────────────
const rawContent = $node['OpenAI'].json?.message?.content;

if (!rawContent || rawContent.trim() === '') {
  const reason = $node['OpenAI'].json?.message?.finish_reason || 'unknown';
  throw new Error(`OpenAI returned empty content. Finish reason: ${reason}. Check API quota or prompt length.`);
}

// Normalise literal \t then strip code fences
const itineraryRaw = rawContent.replace(/\\t/g, '\t').replace(/```[\w]*\n?/g,'').replace(/```/g,'').trim();

const itineraryLines = itineraryRaw.split('\n');
let formattedItinerary = '';
let inDailySchedule = false;
let inCostSummary   = false;
let scheduleLines   = [];
let costSummaryRows = [];

const formatDailySchedule = (lines) => {
  let output = '<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">Daily Schedule:</strong>';
  const joined = lines.join(' ');
  const daySections = joined.match(/(Day \d+:.*?)(?=(Day \d+:|$))/g);
  if (!daySections) return output + '<br>';
  daySections.forEach((dayMatch, index) => {
    const dayLabelMatch = dayMatch.match(/(Day \d+:[^\-]*)/);
    if (!dayLabelMatch) return;
    const dayLabel = dayLabelMatch[1].trim();
    const subItems = dayMatch.match(/- (Morning|Afternoon|Evening):.*?(?=(Day \d+:|- (Morning|Afternoon|Evening):|$))/g);
    output += `<strong>${dayLabel}</strong>`;
    if (subItems) { output += `<div style="margin:4px 0 8px 12px;">${subItems.map(i=>i.trim()).join('<br>')}</div>`; }
    if (index < daySections.length - 1) output += '<br>';
  });
  return output + '<br>';
};

for (let line of itineraryLines) {
  line = line.trim();
  if (!line) {
    if (inDailySchedule) { formattedItinerary += formatDailySchedule(scheduleLines); inDailySchedule=false; scheduleLines=[]; }
    else if (inCostSummary) { inCostSummary=false; formattedItinerary+=`<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`; costSummaryRows=[]; }
    else { formattedItinerary += '<br>'; }
    continue;
  }
  const lower = line.toLowerCase();
  if (lower.startsWith('daily schedule:')) { inDailySchedule=true; scheduleLines=[]; continue; }
  if (inDailySchedule) { scheduleLines.push(line); continue; }
  if (lower.startsWith('cost summary:')) { formattedItinerary+=`<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">Cost Summary:</strong>`; inCostSummary=true; continue; }
  if (inCostSummary && line.includes('\t')) {
    const parts=line.split('\t').map(s=>s.trim()); const cat=parts[0]||''; const cost=parts[1]||'';
    const isBold=cat.startsWith('Total')||cat.startsWith('Remaining Budget');
    const cellStyle=isBold?'border:1px solid #e0e0e0;padding:8px;background:#f0f0f0;font-weight:bold;':'border:1px solid #e0e0e0;padding:8px;';
    costSummaryRows.push(`<tr><td style="${cellStyle}">${cat}</td><td style="${cellStyle}">${cost}</td></tr>`); continue;
  }
  if (inCostSummary) { inCostSummary=false; formattedItinerary+=`<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`; costSummaryRows=[]; }
  if (line.endsWith(':')) { formattedItinerary+=`<strong style="font-size:16px;color:#2a4a6e;display:block;margin:15px 0 5px 0;">${line}</strong>`; }
  else { formattedItinerary+=`${line}<br>`; }
}
if (inDailySchedule && scheduleLines.length>0) formattedItinerary+=formatDailySchedule(scheduleLines);
if (costSummaryRows.length>0) formattedItinerary+=`<table style="border-collapse:collapse;width:100%;margin:10px 0;font-size:14px;">${costSummaryRows.join('')}</table><br>`;

return [{ json: { ...$json, itinerary: formattedItinerary } }];

const destination      = $json.destinationCity   || 'Your Destination';
const departure        = $json.departureLocation  || 'Not specified';
const flexDates        = $json.flexDates          || false;
const tripMode         = $json.tripMode           || 'single';
const destinationLegs  = $json.destinationLegs    || null;
const travelDates      = flexDates
  ? 'Flexible — Genie will suggest the best time'
  : `${$json.startDate||'N/A'} to ${$json.endDate||'N/A'}`;
const budget           = $json.budget             || 'N/A';
const groupSize        = $json.groupSize          || 'N/A';
const tripType         = $json.tripType           || 'N/A';
const travelPace       = $json.travelPace         || '';
const budgetTier       = $json.budgetTier         || 'Standard';
const accommodationType= $json.accommodationType  || 'Not specified';
const amenities        = Array.isArray($json.amenities) ? $json.amenities.join(', ') : ($json.amenities||'Not specified');
const bedrooms         = $json.bedrooms           || 'N/A';
const bathrooms        = $json.bathrooms          || 'N/A';
const ageRange         = Array.isArray($json.ageRange) ? $json.ageRange.join(', ') : ($json.ageRange||'');
const itineraryContent = $json.itinerary          || 'Itinerary details not available.';

const tierBadge  = { Economy: '🟢 Economy', Standard: '🔵 Standard', Elite: '⭐ Elite' }[budgetTier] || budgetTier;
const paceLabel  = { Relaxed: '🌅 Relaxed', Balanced: '🌊 Balanced', Active: '🏄 Active' }[travelPace] || travelPace;

// Build destination display — route for multi, single city for single
const isMulti = tripMode === 'multi' && Array.isArray(destinationLegs) && destinationLegs.length >= 2;
const destinationDisplay = isMulti
  ? destinationLegs.map(l => l.city).join(' → ')
  : destination;
const stopsRow = isMulti
  ? `<p style="color:#333;font-size:15px;margin:8px 0;line-height:1.5;"><strong style="color:#023e8a;">🗺️ Stops:</strong> ${destinationLegs.length} cities — ${destinationLegs.map((l,i)=>`Stop ${i+1}: ${l.city} (${l.checkIn} → ${l.checkOut})`).join(' &nbsp;|&nbsp; ')}</p>`
  : '';

const metaRow = (label, value) =>
  `<p style="color:#333;font-size:15px;margin:8px 0;line-height:1.5;"><strong style="color:#023e8a;">${label}:</strong> ${value}</p>`;

const emailHtml = `
<div style="font-family:'Helvetica Neue',Arial,sans-serif;max-width:660px;margin:0 auto;background:#f8fafc;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(105deg,#023e8a,#0077b6);padding:26px 28px;border-radius:10px 10px 0 0;text-align:center;">
    <h1 style="color:#fff;margin:0;font-size:26px;font-family:Georgia,serif;">🏨 Your ${isMulti ? 'Multi-Destination' : 'City & Stays'} Itinerary</h1>
    <p style="color:rgba(255,255,255,0.8);margin:6px 0 0;font-size:14px;">Generated by Voyage Genie · ${tierBadge}</p>
  </div>
  <div style="background:#fff;padding:28px;border-radius:0 0 10px 10px;border:1px solid #e2e8f0;border-top:none;">
    <h2 style="color:#023e8a;font-size:18px;margin:0 0 16px;border-bottom:2px solid #eaf4fb;padding-bottom:10px;">Trip Overview</h2>
    ${metaRow('📍 Destination', destinationDisplay)}
    ${stopsRow}
    ${metaRow('✈️ Departing from', departure)}
    ${metaRow('📅 Dates', travelDates)}
    ${metaRow('🧳 Trip Type', tripType)}
    ${paceLabel ? metaRow('⚡ Travel Pace', paceLabel) : ''}
    ${metaRow('⭐ Plan Tier', tierBadge)}
    ${metaRow('👥 Group Size', groupSize)}
    ${metaRow('🏠 Accommodation', `${accommodationType} · ${bedrooms} bed · ${bathrooms} bath`)}
    ${metaRow('✨ Amenities', amenities)}
    ${ageRange ? metaRow('👨‍👩‍👧 Age Ranges', ageRange) : ''}
    ${metaRow('💵 Budget', '$' + budget)}
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:20px 0;">
    <h3 style="color:#023e8a;font-size:16px;margin:0 0 14px;">Your Itinerary</h3>
    <div style="background:#f8fafc;padding:20px;border-radius:8px;font-size:14px;line-height:1.7;color:#1e293b;border:1px solid #e2e8f0;">
      ${itineraryContent}
    </div>
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0 16px;">
    <p style="color:#64748b;font-size:12px;text-align:center;margin:0;">
      Generated by <strong>Voyage Genie</strong> 🌟 &nbsp;|&nbsp; Plan Less, Explore More
    </p>
  </div>
</div>`;

const sessionId = [Date.now().toString(36), Math.random().toString(36).slice(2,7)].join('-');
const subject   = isMulti
  ? `Your ${tierBadge} Multi-Stop Itinerary: ${destinationDisplay} – Voyage Genie`
  : `Your ${tierBadge} Airbnb & Hotel Itinerary for ${destination} – Voyage Genie`;

const formData = {
  departureLocation: departure, destinationCity: destinationDisplay,
  startDate: $json.startDate||'', endDate: $json.endDate||'',
  flexDates, tripMode, destinationLegs,
  tripType, travelPace, budgetTier,
  accommodationType, bedrooms, bathrooms, budget, groupSize,
  amenities: $json.amenities || [],
  ageRange:  $json.ageRange  || []
};

return [{ json: {
  sessionId,
  itineraryHtml:   itineraryContent,
  emailHtml:       emailHtml,
  resolvedEmail:   ($json.email||'').trim(),
  resolvedSubject: subject,
  resolvedMessage: emailHtml,
  formData
}}];

const EMAIL_WEBHOOK = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const MAX_RETRIES   = 2;
const RETRY_DELAY   = 1500;

const payload = { resolvedEmail: $json.resolvedEmail, resolvedSubject: $json.resolvedSubject, resolvedMessage: $json.resolvedMessage };

if (!payload.resolvedEmail || payload.resolvedEmail === '') {
  return $input.all();
}

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
let lastError;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    await $http({ method: 'POST', url: EMAIL_WEBHOOK, body: payload, headers: { 'Content-Type': 'application/json' } });
    return $input.all();
  } catch (err) {
    lastError = err;
    if (attempt < MAX_RETRIES) await sleep(RETRY_DELAY);
  }
}
console.error(`Email delivery failed after ${MAX_RETRIES} attempts: ${lastError?.message}`);
return $input.all();

return [{ json: {
  sessionId:     $json.sessionId,
  redirectUrl:   $json.redirectUrl,
  itineraryData: $json.itineraryData,
  itineraryHtml: $json.itineraryHtml,
  emailHtml:     $json.emailHtml
}}];

let method = $json.method;
if (!method) { method = $json.headers?.[':method'] || 'POST'; }
return [{ json: { ...$json, method: method } }];

const body = $json.body || $json;
const destination  = body.destinationCity  || body.destination  || 'unknown';
const departure    = body.departureLocation|| body.departure    || '';
const budget       = body.budget           || '0';
const tripType     = body.tripType         || 'Not specified';
const startDate    = body.startDate        || '';
const endDate      = body.endDate          || '';
const accommodationType = body.accommodationType || body.propertyType || 'Entire Home';

const accomLabel = accommodationType && accommodationType !== 'No preference' ? accommodationType : 'hotel or Airbnb';
const prompt = `The user has a city & stay itinerary for ${destination}. Budget: $${budget}. Trip type: ${tripType}. Accommodation preference: ${accomLabel}${startDate ? `. Dates: ${startDate} to ${endDate}` : ''}.

Suggest 3 alternative destinations with a similar vibe that:
- Match the same travel style and budget
- Suit a ${tripType} traveler
- Have good ${accomLabel} options

For each destination:
- Destination name and country
- Why it suits this traveler (vibe, culture, ease of travel)
- Estimated total cost (flights + 7 nights accommodation)
- Best area to stay
- Top 3 experiences
- Booking link matching their accommodation type (hotel → Booking.com, Airbnb → airbnb.com)

Format with clear headings and bullet points.`;

return [{ json: { ...body, prompt } }];

const rawContent = $node['OpenAI New Suggestion'].json?.message?.content;
if (!rawContent || rawContent.trim() === '') throw new Error('OpenAI New Suggestion returned empty content.');
const sessionId = [Date.now().toString(36), Math.random().toString(36).slice(2,7)].join('-');
return [{ json: { sessionId, suggestions: rawContent.trim(), suggestionsHtml: rawContent.trim().replace(/\n/g,'<br>') } }];
